(()=>{'use strict';if(!document.querySelector('.menu-content'))return;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}
function translated(tag,es,en,cls){const n=el(tag,document.documentElement.lang==='en'?(en||es):es,cls);n.dataset.es=escape(es);n.dataset.en=escape(en||es);return n}
const price=p=>p.price===null?translated('span','Consultar','Ask us','price'):el('span',new Intl.NumberFormat('es-ES',{minimumFractionDigits:2,maximumFractionDigits:2}).format(p.price)+' €'+(p.unit==='100g'?' / 100 g':''),'price');
(async()=>{try{const r=await fetch('/api/app?action=menu',{cache:'no-store'});if(!r.ok)return;const {products,categories}=await r.json();if(!Array.isArray(products)||!Array.isArray(categories))return;const grid=document.querySelector('.menu-photo-grid');grid.replaceChildren();for(const p of products){const card=el('article',undefined,'menu-dish');card.dataset.category=p.category;card.dataset.search=p.name+' '+(p.nameEn||'');const photo=el('div',undefined,'dish-photo'),image=el('img');image.src=p.image;image.alt=p.name;image.loading='lazy';image.decoding='async';photo.append(image);const body=el('div',undefined,'dish-card-body'),heading=el('div');heading.append(translated('h2',p.name,p.nameEn),price(p));body.append(heading);if(p.description)body.append(translated('p',p.description,p.descriptionEn));card.append(photo,body);grid.append(card)}
const complete=document.querySelector('.complete-menu');complete.replaceChildren();for(const category of categories){const rows=products.filter(p=>p.category===category.id);if(!rows.length)continue;const section=el('section',undefined,'menu-category');section.id=category.id;section.dataset.category=category.id;const title=el('div',undefined,'menu-category-title');title.append(translated('h3',category.es,category.en));section.append(title);for(const p of rows){const row=el('div',undefined,'menu-row');row.dataset.search=p.name+' '+(p.nameEn||'');const copy=el('div');copy.append(translated('h4',p.name,p.nameEn));if(p.description)copy.append(translated('p',p.description,p.descriptionEn));row.append(copy,price(p));section.append(row)}complete.append(section)}
document.querySelector('[data-filter][aria-pressed=true]')?.click();
}catch{ /* Keep the existing menu available if the live catalog cannot load. */ }})();
})();
